// ── 다크 테마 안내 화면 전용 색상 ─────────────────────────────────────────────
private val NavBg           = Color(0xFF1C1C1E)   // 화면 배경
private val NavSurface      = Color(0xFF2C2C2E)   // 카드 배경
private val NavDivider      = Color(0xFF3A3A3C)   // 구분선
private val NavAmber        = Color(0xFFF2B705)   // 노란색 (남은 거리·시간, 위치 카드)
private val NavAmberOnCard  = Color(0xFF1C1C1E)   // 노란 카드 위 텍스트
private val NavExit         = Color(0xFFFF6B6B)   // X 버튼 (안내 종료)
private val NavTabInactive  = Color(0xFF636366)   // 비활성 탭 아이콘/레이블

// ─────────────────────────────────────────────────────────────────────────────

/**
 * 네비게이션 안내 화면.
 *
 * 고대비 다크 UI로 구성됩니다.
 *   - 상단: 남은 거리 / 남은 시간 지표
 *   - 중단: 현재 위치 카드 (노란 배경)
 *   - 하단: 안내 종료 카드
 *   - 최하단: 탭 바
 *
 * @param uiState   [NavigationUiState] — ViewModel 에서 수집한 상태
 * @param onAction  사용자 인터랙션을 ViewModel 로 전달하는 콜백
 */
@Composable
fun NavigationScreen(
    uiState: NavigationUiState,
    onAction: (NavigationUiAction) -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .background(NavBg),
    ) {
        // 상단 지표 행
        NavigationMetricsRow(
            distanceLabel = uiState.stepCard.metrics.getOrNull(0)?.value ?: "-",
            timeLabel = uiState.stepCard.metrics.getOrNull(1)?.value ?: "-",
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = EumSpacing.medium)
                .padding(top = EumSpacing.large),
        )

        Spacer(modifier = Modifier.height(EumSpacing.large))

        // 현재 위치 카드 (flex 1)
        NavigationLocationCard(
            locationLabel = uiState.mapOverlay.currentLocation?.label ?: "현재 위치",
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f)
                .padding(horizontal = EumSpacing.medium),
        )

        Spacer(modifier = Modifier.height(EumSpacing.medium))

        // 안내 종료 카드
        NavigationExitCard(
            label = uiState.exitCta.label,
            enabled = uiState.isExitEnabled,
            onClick = { onAction(NavigationUiAction.ExitNavigationClicked) },
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = EumSpacing.medium),
        )

        Spacer(modifier = Modifier.height(EumSpacing.medium))

        // 탭 바
        NavigationTabBar(
            modifier = Modifier.fillMaxWidth(),
        )
    }
}

// ── 상단 지표 행 ──────────────────────────────────────────────────────────────

@Composable
private fun NavigationMetricsRow(
    distanceLabel: String,
    timeLabel: String,
    modifier: Modifier = Modifier,
) {
    Row(
        modifier = modifier,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // 남은 거리
        NavigationMetricItem(
            label = "남은 거리",
            value = distanceLabel,
            modifier = Modifier
                .weight(1f)
                .semantics(mergeDescendants = true) {
                    contentDescription = "남은 거리 $distanceLabel"
                },
        )

        // 구분선
        Box(
            modifier = Modifier
                .width(1.5.dp)
                .height(72.dp)
                .background(NavDivider),
        )

        // 남은 시간
        NavigationMetricItem(
            label = "남은 시간",
            value = timeLabel,
            modifier = Modifier
                .weight(1f)
                .semantics(mergeDescendants = true) {
                    contentDescription = "남은 시간 $timeLabel"
                },
        )
    }
}

@Composable
private fun NavigationMetricItem(
    label: String,
    value: String,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(EumSpacing.xSmall),
    ) {
        Text(
            text = label,
            style = MaterialTheme.typography.bodyMedium,
            color = NavTabInactive,
            textAlign = TextAlign.Center,
        )
        Text(
            text = value,
            fontSize = 56.sp,
            fontWeight = FontWeight.ExtraBold,
            color = NavAmber,
            textAlign = TextAlign.Center,
            letterSpacing = (-1).sp,
        )
    }
}

// ── 현재 위치 카드 ────────────────────────────────────────────────────────────

@Composable
private fun NavigationLocationCard(
    locationLabel: String,
    modifier: Modifier = Modifier,
) {
    Surface(
        modifier = modifier.semantics(mergeDescendants = true) {
            contentDescription = "현재 위치: $locationLabel"
        },
        shape = RoundedCornerShape(EumRadius.large),
        color = NavAmber,
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(EumSpacing.xLarge),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
        ) {
            Icon(
                painter = painterResource(id = R.drawable.ic_voice_location_pin),
                contentDescription = null,
                tint = NavAmberOnCard,
                modifier = Modifier.size(72.dp),
            )
            Spacer(modifier = Modifier.height(EumSpacing.medium))
            Text(
                text = locationLabel,
                fontSize = 32.sp,
                fontWeight = FontWeight.ExtraBold,
                color = NavAmberOnCard,
                textAlign = TextAlign.Center,
            )
        }
    }
}

// ── 안내 종료 카드 ────────────────────────────────────────────────────────────

@Composable
private fun NavigationExitCard(
    label: String,
    enabled: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val interactionSource = remember { MutableInteractionSource() }
    val alpha = if (enabled) 1f else 0.4f

    Surface(
        modifier = modifier
            .clip(RoundedCornerShape(EumRadius.large))
            .clickable(
                enabled = enabled,
                interactionSource = interactionSource,
                indication = rememberRipple(color = NavExit),
                onClick = onClick,
            )
            .semantics {
                role = Role.Button
                contentDescription = if (enabled) "$label. 탭하여 안내를 종료합니다." else "$label. 비활성 상태"
            },
        shape = RoundedCornerShape(EumRadius.large),
        color = NavSurface.copy(alpha = alpha),
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = EumSpacing.large),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(EumSpacing.small),
        ) {
            // X 버튼
            Box(
                modifier = Modifier
                    .size(64.dp)
                    .background(
                        color = NavExit.copy(alpha = alpha),
                        shape = CircleShape,
                    ),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    painter = painterResource(id = R.drawable.ic_action_close),
                    contentDescription = null,
                    tint = NavAmberOnCard,
                    modifier = Modifier.size(28.dp),
                )
            }

            Text(
                text = label,
                fontSize = 28.sp,
                fontWeight = FontWeight.Bold,
                color = Color.White.copy(alpha = alpha),
                textAlign = TextAlign.Center,
            )
        }
    }
}

// ── 하단 탭 바 ────────────────────────────────────────────────────────────────

@Composable
private fun NavigationTabBar(
    modifier: Modifier = Modifier,
) {
    Surface(
        modifier = modifier,
        color = NavBg,
    ) {
        Column {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(NavDivider),
            )
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = EumSpacing.medium, vertical = EumSpacing.small),
            ) {
                NavigationTabBarItem(
                    iconRes = R.drawable.ic_nav_home_filled,
                    label = stringResource(id = R.string.route_map),
                    selected = true,
                    modifier = Modifier.weight(1f),
                )
                NavigationTabBarItem(
                    iconRes = R.drawable.ic_nav_bookmark_outline,
                    label = stringResource(id = R.string.route_saved_route),
                    selected = false,
                    modifier = Modifier.weight(1f),
                )
                NavigationTabBarItem(
                    iconRes = R.drawable.ic_nav_category_grid,
                    label = stringResource(id = R.string.route_report),
                    selected = false,
                    modifier = Modifier.weight(1f),
                )
                NavigationTabBarItem(
                    iconRes = R.drawable.ic_nav_mypage,
                    label = stringResource(id = R.string.route_my_page),
                    selected = false,
                    modifier = Modifier.weight(1f),
                )
            }
        }
    }
}

@Composable
private fun NavigationTabBarItem(
    iconRes: Int,
    label: String,
    selected: Boolean,
    modifier: Modifier = Modifier,
) {
    val iconColor = if (selected) NavAmber else NavTabInactive
    val labelColor = if (selected) NavAmber else NavTabInactive

    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(EumSpacing.xSmall),
    ) {
        Icon(
            painter = painterResource(id = iconRes),
            contentDescription = label,
            tint = iconColor,
            modifier = Modifier.size(24.dp),
        )
        Text(
            text = label,
            style = MaterialTheme.typography.labelLarge,
            color = labelColor,
            fontSize = 10.sp,
        )
    }
}

